    presentation: [
      { title: "line-height", points: ["Множник відносно розміру шрифту (1.5, 1.6)", "Впливає на читабельність довгого тексту", "Занизький line-height — рядки «злипаються»"] },
      { title: "Вирівнювання і регістр", points: ["text-align: left/center/right/justify", "text-transform: uppercase/lowercase/capitalize", "letter-spacing — відстань між буквами, для капса"] },
    ],
    task: "Стилізуй .article: line-height (1.4-1.8) і text-align.",
    starter: "",
