// Milestone lessons whose submitted HTML feeds the growing "Мій сайт" project.
const HEADER_MILESTONE = "html-17";
const MAIN_MILESTONES = ["html-41", "html-3", "html-42", "html-4", "html-5", "html-6", "html-11", "html-8"];

// Milestone CSS lessons whose submitted rules style the same growing site —
// order is the order they're concatenated into project.css.
const CSS_MILESTONES = ["css-41", "css-3", "css-4", "css-42", "css-21", "css-9", "css-14", "css-17", "css-18", "css-19", "css-20", "css-34", "css-40"];

function renderProjectCss(project) {
  const blocks = project.blocks || {};
  return [...CSS_MILESTONES, ...FRONTEND_CSS_MILESTONES].map((id) => blocks[id]).filter(Boolean).join("\n\n");
}

// Milestone JS lessons whose submitted code brings the same growing site to
// life. Each targets either a fixed part of the page (footer, or the
// header/main/footer never change shape) or the FIXED class names/tags that
// the HTML/CSS milestones themselves require (.cards/.card-item, "main
// input"/"main button") — never an id, since ids in freeform HTML milestones
// like html-8 are chosen by the learner and can't be relied on here.
const JS_MILESTONES = ["js-41", "js-42", "js-43", "js-44"];

function renderProjectJs(project) {
  const blocks = project.blocks || {};
  return [...JS_MILESTONES, ...FRONTEND_JS_MILESTONES].map((id) => blocks[id]).filter(Boolean).join("\n\n");
}

// Produces the FULL document — DOCTYPE, <html lang>, <head> with the meta
// tags taught in html-2/html-14, and <body> with the growing header/main/footer —
// so "Мій сайт" always looks like a real file, not just a body fragment.
function renderProjectHtml(project, theme, siteName) {
  const name = siteName ?? project.siteName;
  const blocks = project.blocks || {};
  const header =
    blocks[HEADER_MILESTONE] ||
    `<header>\n    <h1>${name}</h1>\n    <nav>\n${theme.navLinks.map((l) => `      <a href="#">${l}</a>`).join("\n")}\n    </nav>\n  </header>`;
  const mainBlocks = [...MAIN_MILESTONES, ...FRONTEND_MAIN_MILESTONES].map((id) => blocks[id]).filter(Boolean);
  const main = mainBlocks.length
    ? `<main>\n${mainBlocks.map((b) => "    " + b.split("\n").join("\n    ")).join("\n\n")}\n  </main>`
    : `<main>\n    <!-- Тут з'являться нові блоки в міру проходження уроків -->\n  </main>`;
  const footer = `<footer>\n    <p>© 2025 ${name}</p>\n  </footer>`;
  return `<!DOCTYPE html>\n<html lang="uk">\n<head>\n  <meta charset="UTF-8">\n  <meta name="viewport" content="width=device-width, initial-scale=1.0">\n  <title>${name}</title>\n  <meta name="description" content="${name} — ${theme.description}">\n</head>\n<body>\n  ${header}\n  ${main}\n  ${footer}\n</body>\n</html>`;
}

async function loadProject() {
  try {
    const raw = localStorage.getItem("00100101-project");
    if (raw) return JSON.parse(raw);
  } catch (e) {
    /* no saved project yet */
  }
  return defaultProject();
}

async function saveProject(p) {
  try {
    localStorage.setItem("00100101-project", JSON.stringify(p));
  } catch (e) {
    console.error("Не вдалося зберегти проєкт", e);
  }
}

