function defaultProgress() {
  return { completed: { html: [], css: [], javascript: [], english: [] }, xp: 0, unlocked: [] };
}

async function loadProgress() {
  try {
    const raw = localStorage.getItem("00100101-progress");
    if (raw) return JSON.parse(raw);
  } catch (e) {
    /* no saved progress yet */
  }
  return defaultProgress();
}

async function saveProgress(p) {
  try {
    localStorage.setItem("00100101-progress", JSON.stringify(p));
  } catch (e) {
    console.error("Не вдалося зберегти прогрес", e);
  }
}

function computeUnlocked(progress) {
  const total = Object.values(progress.completed).reduce((a, arr) => a + arr.length, 0);
  const unlocked = [];
  if (total >= 1) unlocked.push("first-code");
  if (progress.completed.html?.length >= 1) unlocked.push("first-html");
  if (progress.completed.css?.length >= 1) unlocked.push("first-css");
  if (progress.completed.javascript?.length >= 1) unlocked.push("first-js");
  if (total >= 10) unlocked.push("ten-lessons");
  if (progress.completed.html?.length === HTML_LESSONS.length) unlocked.push("html-master");
  if (progress.completed.css?.length === CSS_LESSONS.length) unlocked.push("css-master");
  if (progress.completed.javascript?.length === JS_LESSONS.length) unlocked.push("js-master");
  if (progress.completed.english?.length >= 1) unlocked.push("first-english");
  if (progress.completed.english?.length === ENGLISH_LESSONS.length) unlocked.push("english-master");
  return unlocked;
}

function parseHTMLDoc(code) {
  return new DOMParser().parseFromString(code, "text/html");
}

// Pyodide (CPython compiled to WebAssembly) loaded lazily from a CDN on first
// use — keeps it out of the main bundle entirely; only Python lessons pay for
// it, and only once (cached in this module-level promise for the session).
let __pyodidePromise = null;
function loadPyodideOnce() {
  if (!__pyodidePromise) {
    __pyodidePromise = new Promise((resolve, reject) => {
      const pyodideBase = import.meta.env.BASE_URL + "pyodide/";
      const script = document.createElement("script");
      script.type = "module";
      script.textContent =
        `import { loadPyodide } from "${pyodideBase}pyodide.mjs"; window.__loadPyodideFn = loadPyodide; window.dispatchEvent(new Event("__pyodide-script-ready"));`;
      window.addEventListener(
        "__pyodide-script-ready",
        () => {
          window.__loadPyodideFn({ indexURL: pyodideBase }).then(resolve, reject);
        },
        { once: true }
      );
      script.onerror = () => reject(new Error("Не вдалося завантажити локальний файл Pyodide."));
      document.head.appendChild(script);
    }).catch((err) => {
      __pyodidePromise = null;
      throw new Error("Не вдалося завантажити Python-середовище (Pyodide): " + String(err.message || err));
    });
  }
  return __pyodidePromise;
}

// Runs learner code + testCode in a FRESH Python namespace each time (so one
// lesson's variables never leak into the next), captures print() output, and
// expects testCode to set __result__ = {"pass": True/False, "message": "..."}.
async function runPythonCheck(code, testCode) {
  const pyodide = await loadPyodideOnce();
  const logs = [];
  pyodide.setStdout({ batched: (line) => logs.push(line) });
  pyodide.setStderr({ batched: (line) => logs.push(line) });
  const namespace = pyodide.globals.get("dict")();
  try {
    try {
      await pyodide.runPythonAsync(code || "", { globals: namespace });
    } catch (err) {
      return { logs, testResult: { pass: false, message: "Помилка виконання коду: " + String(err.message || err).split("\n").pop() } };
    }
    try {
      namespace.set("__logs", pyodide.toPy(logs));
      await pyodide.runPythonAsync(
        (testCode || '__result__ = {"pass": True, "message": ""}') + "\n",
        { globals: namespace }
      );
    } catch (err) {
      return { logs, testResult: { pass: false, message: "Помилка в перевірці: " + String(err.message || err).split("\n").pop() } };
    }
    const raw = namespace.get("__result__");
    const testResult = raw && raw.toJs ? raw.toJs() : { pass: false, message: "Перевірка не повернула результат." };
    return { logs, testResult };
  } finally {
    namespace.destroy();
  }
}

// TypeScript compiler (classic UMD build) loaded lazily from a self-hosted
// static file — same reasoning as Pyodide: no CDN/npm access at runtime, and
// only TS lessons pay for the 8.6MB bundle, once per session. The script is a
// classic (non-module) script, so it creates a plain global `ts` variable.
let __tsPromise = null;
function loadTypeScriptOnce() {
  if (!__tsPromise) {
    __tsPromise = new Promise((resolve, reject) => {
      if (window.ts) { resolve(window.ts); return; }
      const script = document.createElement("script");
      script.src = import.meta.env.BASE_URL + "typescript/typescript.js";
      script.onload = () => resolve(window.ts);
      script.onerror = () => reject(new Error("Не вдалося завантажити локальний файл TypeScript."));
      document.head.appendChild(script);
    }).catch((err) => {
      __tsPromise = null;
      throw new Error("Не вдалося завантажити компілятор TypeScript: " + String(err.message || err));
    });
  }
  return __tsPromise;
}

// TypeScript's own lib.*.d.ts files (bundled once at build time into a single
// JSON map, see scripts/bundle-ts-libs), fetched lazily so real semantic type
// checking (not just syntax transpilation) works against real DOM/ES types.
let __tsLibFilesPromise = null;
function loadTsLibFilesOnce() {
  if (!__tsLibFilesPromise) {
    __tsLibFilesPromise = fetch(import.meta.env.BASE_URL + "typescript/lib-files.json")
      .then((r) => r.json())
      .catch((err) => {
        __tsLibFilesPromise = null;
        throw new Error("Не вдалося завантажити файли типів TypeScript: " + String(err.message || err));
      });
  }
  return __tsLibFilesPromise;
}

function formatTsDiagnostics(ts, diagnostics) {
  return diagnostics
    .map((d) => {
      let loc = "";
      if (d.file && d.start !== undefined) {
        const { line, character } = d.file.getLineAndCharacterOfPosition(d.start);
        loc = `Рядок ${line + 1}:${character + 1} — `;
      }
      return loc + ts.flattenDiagnosticMessageText(d.messageText, "\n");
    })
    .join("\n");
}

// Real type-checking (not just syntax stripping) via a virtual in-memory
// CompilerHost backed by TypeScript's own bundled lib .d.ts files. Returns
// { ok:false, message } on a type error, or { ok:true, emittedJs } with the
// compiled JS ready to run in the existing JS sandbox (buildJsSandboxDoc).
async function runTypeScriptCheck(code) {
  const ts = await loadTypeScriptOnce();
  const libFiles = await loadTsLibFilesOnce();
  const fileName = "input.ts";
  const compilerOptions = {
    target: ts.ScriptTarget.ES2017,
    lib: ["lib.es2017.d.ts", "lib.dom.d.ts"],
    strict: true,
    noImplicitAny: true,
    module: ts.ModuleKind.None,
    noEmitOnError: false,
  };
  const outputs = {};
  const host = {
    getSourceFile: (name, langVersion) => {
      if (name === fileName) return ts.createSourceFile(name, code, langVersion, true);
      if (Object.prototype.hasOwnProperty.call(libFiles, name)) {
        return ts.createSourceFile(name, libFiles[name], langVersion, true);
      }
      return undefined;
    },
    getDefaultLibFileName: (options) => ts.getDefaultLibFileName(options),
    writeFile: (name, data) => { outputs[name] = data; },
    getCurrentDirectory: () => "/",
    getCanonicalFileName: (name) => name,
    useCaseSensitiveFileNames: () => true,
    getNewLine: () => "\n",
    fileExists: (name) => name === fileName || Object.prototype.hasOwnProperty.call(libFiles, name),
    readFile: (name) => (name === fileName ? code : libFiles[name]),
    directoryExists: () => true,
    getDirectories: () => [],
  };
  const program = ts.createProgram([fileName], compilerOptions, host);
  const diagnostics = ts.getPreEmitDiagnostics(program);
  if (diagnostics.length > 0) {
    return { ok: false, message: formatTsDiagnostics(ts, diagnostics) };
  }
  program.emit();
  const emittedJs = outputs[fileName.replace(/\.ts$/, ".js")] || "";
  return { ok: true, emittedJs };
}

// SQL.js (SQLite compiled to WebAssembly) loaded lazily from a self-hosted
// static file — same reasoning as Pyodide/TypeScript: no CDN/npm access at
// runtime, and only SQL lessons pay for it, once per session. The script is
// a classic (non-module) script exposing a global initSqlJs() factory.
let __sqlJsPromise = null;
function loadSqlJsOnce() {
  if (!__sqlJsPromise) {
    __sqlJsPromise = new Promise((resolve, reject) => {
      if (window.initSqlJs) { resolve(window.initSqlJs); return; }
      const script = document.createElement("script");
      script.src = import.meta.env.BASE_URL + "sql/sql-wasm.js";
      script.onload = () => resolve(window.initSqlJs);
      script.onerror = () => reject(new Error("Не вдалося завантажити локальний файл SQL.js."));
      document.head.appendChild(script);
    })
      .then((initSqlJs) => initSqlJs({ locateFile: (f) => import.meta.env.BASE_URL + "sql/" + f }))
      .catch((err) => {
        __sqlJsPromise = null;
        throw new Error("Не вдалося завантажити SQL-середовище (SQL.js): " + String(err.message || err));
      });
  }
  return __sqlJsPromise;
}

// Runs setupSql (schema + seed data) against a FRESH in-memory SQLite database
// each time (so one lesson's data never leaks into the next), then the
// learner's query, then testCode — which gets both the raw db handle (to run
// its own follow-up queries, needed for INSERT/UPDATE/DELETE lessons) and
// execResult (db.exec's own return value, useful for SELECT lessons).
async function runSqlCheck(setupSql, code, testCode) {
  const SQL = await loadSqlJsOnce();
  const db = new SQL.Database();
  try {
    try {
      db.run(setupSql || "");
    } catch (err) {
      return { execResult: [], testResult: { pass: false, message: "Помилка в підготовці даних уроку: " + String(err.message || err) } };
    }
    let execResult;
    try {
      execResult = db.exec(code || "");
    } catch (err) {
      return { execResult: [], testResult: { pass: false, message: "Помилка в SQL-запиті: " + String(err.message || err) } };
    }
    try {
      const testFn = new Function("db", "execResult", testCode || "return {pass:true, message:''};");
      const testResult = testFn(db, execResult);
      return { execResult, testResult };
    } catch (err) {
      return { execResult, testResult: { pass: false, message: "Помилка в перевірці: " + String(err.message || err) } };
    }
  } finally {
    db.close();
  }
}

// Babel Standalone loaded lazily from a self-hosted static file — same
// reasoning as Pyodide/TypeScript/SQL.js: no CDN access at runtime, and only
// React lessons pay for it, once per session. It's used ONLY in the parent
// window to transpile the learner's JSX into plain JS (React.createElement
// calls); the resulting JS then runs inside the existing iframe sandbox via
// buildJsSandboxDoc, exactly like the TypeScript course's emitted JS does.
let __babelPromise = null;
function loadBabelOnce() {
  if (!__babelPromise) {
    __babelPromise = new Promise((resolve, reject) => {
      if (window.Babel) { resolve(window.Babel); return; }
      const script = document.createElement("script");
      script.src = import.meta.env.BASE_URL + "react/babel.min.js";
      script.onload = () => resolve(window.Babel);
      script.onerror = () => reject(new Error("Не вдалося завантажити локальний файл Babel."));
      document.head.appendChild(script);
    }).catch((err) => {
      __babelPromise = null;
      throw new Error("Не вдалося завантажити компілятор JSX (Babel): " + String(err.message || err));
    });
  }
  return __babelPromise;
}

// React + ReactDOM aren't bundled into the app itself — lesson code is
// arbitrary learner-written JSX, so it must run inside the same sandboxed
// iframe as every other "js"-family lesson, not in the app's own React tree.
// These <script> tags load the SAME self-hosted UMD builds as a classic
// (non-module) script, exposing window.React / window.ReactDOM inside the
// iframe, before the learner's compiled code runs.
function reactDomTemplate(extraHtml) {
  const base = import.meta.env.BASE_URL;
  return `${extraHtml || '<div id="root"></div>'}
<script src="${base}react/react.development.js"><\/script>
<script src="${base}react/react-dom.development.js"><\/script>`;
}

// Transpiles JSX -> plain JS (React.createElement calls) via Babel's
// "react" preset. Throws with a readable message on a JSX syntax error,
// the same way runTypeScriptCheck surfaces a type error before ever
// touching the iframe sandbox.
async function runReactTranspile(code) {
  const Babel = await loadBabelOnce();
  try {
    return Babel.transform(code, { presets: ["react"], filename: "input.jsx" }).code;
  } catch (err) {
    throw new Error("Помилка JSX: " + String(err.message || err));
  }
}

function buildJsSandboxDoc(code, testCode, domTemplate, harness) {
  const safeCode = code || "";
  const safeTest = testCode || "return {pass:true,message:''}";
  const safeHarness = harness || "";
  return `<!DOCTYPE html><html><body>${domTemplate || '<div id="app"></div>'}<script>
(async function(){
  const __logs = [];
  const origLog = console.log;
  console.log = function(...args){
    __logs.push(args.map(a => { try { return typeof a === 'object' ? JSON.stringify(a) : String(a); } catch(e){ return String(a); } }).join(' '));
    origLog.apply(console, args);
  };
  // Real localStorage throws in a sandboxed (opaque-origin) iframe, so lessons
  // that teach it run against this in-memory shim with the same API instead.
  const __store = {};
  const localStorage = {
    setItem: (k, v) => { __store[k] = String(v); },
    getItem: (k) => (Object.prototype.hasOwnProperty.call(__store, k) ? __store[k] : null),
    removeItem: (k) => { delete __store[k]; },
    clear: () => { for (const k of Object.keys(__store)) delete __store[k]; },
  };
  let testResult = { pass: false, message: 'Код ще не виконано.' };
  try {
    ${safeHarness}
    ${safeCode}
    try {
      testResult = await (async function(){ ${safeTest} })();
    } catch (e2) {
      testResult = { pass: false, message: 'Помилка в перевірці: ' + e2.message };
    }
  } catch (err) {
    parent.postMessage({ type: 'sandbox-result', logs: __logs, testResult: { pass: false, message: 'Помилка виконання коду: ' + err.message } }, '*');
    return;
  }
  parent.postMessage({ type: 'sandbox-result', logs: __logs, testResult }, '*');
})();
<\/script></body></html>`;
}

